public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            if (r == null || r.opportunityId == null || r.contactId == null) {
                throw new SoftCreditException('Opportunity and contact are required.');
            }
            oppIds.add(r.opportunityId);
            contactIds.add(r.contactId);
        }

        // Query 1: opportunities
        Map<Id, Opportunity> opps = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c FROM Opportunity WHERE Id IN :oppIds]
        );

        // Validate everything before any DML
        for (SoftCreditRequest r : requests) {
            Opportunity o = opps.get(r.opportunityId);
            if (o == null) {
                throw new SoftCreditException('Opportunity not found or not accessible: ' + r.opportunityId);
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException('Amount must be greater than zero.');
            }
            if (o.Amount == null || r.amount > o.Amount) {
                throw new SoftCreditException('Amount cannot exceed the opportunity amount.');
            }
            if (o.npsp__Primary_Contact__c != null && o.npsp__Primary_Contact__c == r.contactId) {
                throw new SoftCreditException('Contact is the primary contact of the opportunity.');
            }
        }

        // Query 2: existing contact roles
        Map<String, List<OpportunityContactRole>> rolesByKey = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
            ORDER BY CreatedDate, Id
        ]) {
            String k = key(ocr.OpportunityId, ocr.ContactId);
            if (!rolesByKey.containsKey(k)) {
                rolesByKey.put(k, new List<OpportunityContactRole>());
            }
            rolesByKey.get(k).add(ocr);
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        Map<String, Id> finalRoleId = new Map<String, Id>();
        Map<String, OpportunityContactRole> newRoles = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest r : requests) {
            String k = key(r.opportunityId, r.contactId);
            List<OpportunityContactRole> existing = rolesByKey.get(k);
            if (existing != null && !existing.isEmpty()) {
                OpportunityContactRole keep = existing[0];
                for (Integer i = 1; i < existing.size(); i++) {
                    toDelete.add(existing[i]);
                }
                if (keep.Role != r.role) {
                    toUpdate.add(new OpportunityContactRole(Id = keep.Id, Role = r.role));
                }
                finalRoleId.put(k, keep.Id);
            } else {
                OpportunityContactRole n = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role
                );
                toInsert.add(n);
                newRoles.put(k, n);
            }
        }

        // Query 3: existing partial soft credits
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c p : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
            ORDER BY CreatedDate, Id
        ]) {
            String k = key(p.npsp__Opportunity__c, p.npsp__Contact__c);
            if (!pscByKey.containsKey(k)) {
                pscByKey.put(k, p);
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        for (String k : newRoles.keySet()) {
            finalRoleId.put(k, newRoles.get(k).Id);
        }

        List<npsp__Partial_Soft_Credit__c> pscUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest r : requests) {
            String k = key(r.opportunityId, r.contactId);
            npsp__Partial_Soft_Credit__c existing = pscByKey.get(k);
            npsp__Partial_Soft_Credit__c p;
            if (existing == null) {
                p = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c = r.contactId
                );
            } else {
                p = new npsp__Partial_Soft_Credit__c(Id = existing.Id);
            }
            p.npsp__Amount__c = r.amount;
            p.npsp__Role_Name__c = r.role;
            p.npsp__Contact_Role_ID__c = String.valueOf(finalRoleId.get(k));
            pscUpsert.add(p);
        }
        upsert pscUpsert;
    }

    private static String key(Id oppId, Id contactId) {
        return String.valueOf(oppId) + '|' + String.valueOf(contactId);
    }
}
